            var lo, hi;
            try { lo = this.lower(t); hi = this.upper(t); } catch (e) { lo = NaN; hi = NaN; }
            if (isFinite(lo) && isFinite(hi)) {
              top.push([plotX(t), plotY(hi)]);
              bottom.push([plotX(t), plotY(lo)]);
            }
          }
          if (top.length < 2) return this;
          bottom.reverse();
          var poly = group.polygon(_pointsAttr(top.concat(bottom)))
            .fill({
              color: opts.fill || '#7fb3ff',
              opacity: (opts.opacity == null) ? 0.45 : opts.opacity
            });
          if (opts.stroke) {
            poly.stroke({ color: opts.stroke, width: opts.strokeWidth || 1, linejoin: 'round' });
          } else {
            poly.stroke('none');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /**
     * plotParametric(id, opts) → handle
     *   opts: { x, y, variables=['t'], tDomain=[0,1], samples=200, stroke, width }
     */
    function plotParametric(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['t'];
      var group = _plotFrame.draw.group().attr('id', 'param-' + id);
      var handle = {
        id: id,
        node: group,
        fx: _resolveFn(opts.x, vars),
        fy: _resolveFn(opts.y, vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX: function (src) { this.fx = _resolveFn(src, vars); return this.sample(); },
        setY: function (src) { this.fy = _resolveFn(src, vars); return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.tDomain[0], b = this.tDomain[1], n = Math.max(2, this.samples | 0);
          var pts = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var vx, vy;
            try { vx = this.fx(t); vy = this.fy(t); } catch (e) { vx = NaN; vy = NaN; }
            if (isFinite(vx) && isFinite(vy)) pts.push([plotX(vx), plotY(vy)]);
          }
          if (pts.length >= 2) {
            group.polyline(_pointsAttr(pts))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4', width: opts.width || 2,
                linecap: 'round', linejoin: 'round'
              });
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** integrateSimpson(fn, a, b, n=200) → number. Composite Simpson's rule. */
    function integrateSimpson(fn, a, b, n) {
      n = Math.max(2, n || 200);
      if (n % 2) n++;
      var h = (b - a) / n, s = fn(a) + fn(b);
      for (var i = 1; i < n; i++) s += fn(a + i * h) * ((i % 2) ? 4 : 2);
      return (s * h) / 3;
    }

    /** findRoot(fn, a, b, tol=1e-9) → number | null. Bisection; null if no sign change. */
    function findRoot(fn, a, b, tol) {
      tol = tol || 1e-9;
      var fa = fn(a), fb = fn(b);
      if (!isFinite(fa) || !isFinite(fb) || fa * fb > 0) return null;
      for (var i = 0; i < 200; i++) {
        var m = (a + b) / 2, fm = fn(m);
        if (!isFinite(fm)) return null;
        if (Math.abs(fm) < tol || (b - a) / 2 < tol) return m;
        if (fa * fm < 0) { b = m; } else { a = m; fa = fm; }
      }
      return (a + b) / 2;
    }

    /* ── Equation input binding ──────────────────────────────────────────── */
    /**
     * The error slot is keyed PER INPUT (id "eq-err-<inputId>"), never just
     * "the first .eq-err under my parent": generated figures routinely put
     * several equation inputs under one parent, and a shared slot means a valid
     * edit of field B hides field A's still-current parse error, leaving A's
     * curve stale with nothing on screen to explain why.
     * The .eq-err class is kept so the scaffold CSS still applies.
     *
     * DUPLICATED: keep in sync with _equationErrorSlot in base_scene_new.html.
     */
    function _equationErrorSlot(input) {
      var parent = input.parentNode || document.getElementById('ui');
      if (input.id) {
        var slotId = 'eq-err-' + input.id;
        var byId = document.getElementById(slotId);
        if (byId) return byId;
        var namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      var existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      var span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
    }

    /**
     * _resolveEqTarget(inputId, t) → function(fn, src)
     * Turns one bindEquationInput target into a concrete applier, and THROWS on
     * anything it cannot drive. Silently skipping an unrecognised target is the
     * worst possible outcome: the figure renders, typing changes nothing, and
     * nothing reports it. Throwing makes verify2dHtml catch the mistake at
     * generation time instead of the student discovering it.
     *
     * DUPLICATED: keep in sync with _resolveEqTarget in base_scene_new.html.
     */
    function _resolveEqTarget(inputId, t) {
      if (typeof t === 'function') {
        return function (fn, src) { t(fn, src); };
      }
      if (t && t.handle) {
        var method = t.method || 'setFn';
        if (typeof t.handle[method] !== 'function') {
          throw new Error(
            'bindEquationInput("' + inputId + '"): target handle has no method "' + method +
            '". Use { handle, method: \'...\' } with a method the handle really has ' +
            '(plotFunction: setExpr, setFn; fillBetween: setLower, setUpper; ' +
            'plotParametric: setX, setY).'
          );
        }
        return function (fn) { t.handle[method](fn); };
      }
      if (t && typeof t.setFn === 'function') {
        return function (fn) { t.setFn(fn); };
      }
      throw new Error(
        'bindEquationInput("' + inputId + '"): this target cannot be driven — it is not a ' +
        'function and has no .setFn. Handles without .setFn (fillBetween, plotParametric) ' +
        'must be passed as { handle, method: \'setUpper\' } naming the setter to call.'
      );
    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     *   targets: a plot handle, a { handle, method } pair, a function(fn, src),
     *            or an array of any of those.
     *   opts   : { variables=['x'], onChange(fn, src) }
     *
     * On every valid edit, every target re-samples. On a parse error the last
     * good curve is kept and the message is shown inline — this function NEVER
     * substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_new.html.
     */
    function bindEquationInput(inputId, targets, opts) {
      opts = opts || {};
      var input = document.getElementById(inputId);
      if (!input) throw new Error('bindEquationInput: no element with id "' + inputId + '"');
      var vars = opts.variables || ['x'];
      var list = Array.isArray(targets) ? targets : [targets];
      var slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      var appliers = [];
      for (var k = 0; k < list.length; k++) appliers.push(_resolveEqTarget(inputId, list[k]));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          var fn = compileExpr(src, vars);
          for (var i = 0; i < appliers.length; i++) appliers[i](fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', function () { apply(input.value); });
      apply(input.value);
      return { apply: apply, input: input, errorSlot: slot };
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();
  </script>
</body>

</html>

GLOBALS (do not re-declare): showPopup(title,body), showTooltip(text,event), hideTooltip(), #container (mount target), window.__markRendered() (call once when drawn), 'fig-resize' CustomEvent on document, setUiLayout(mode, sizePx).
  #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel. Docking resizes #container and fires 'fig-resize', so setPlotFrame re-lays the figure out at its new size.

LIBRARY: SVG.js v3 (global: SVG). var draw=SVG().addTo(document.getElementById('container')).size('100%','100%'); var W=600,H=Math.round(W*(3/4)); draw.viewbox(0,0,W,H). font-size in user units (no px). Hover: el.on('mousemove',e=>showTooltip('label',e)).on('mouseleave',()=>hideTooltip()).on('click',()=>showPopup('Title','body')); el.css('cursor','pointer'). window.__markRendered() synchronously at end.
PLOTTING HELPERS (do not re-declare, and do NOT define your own X()/Y() — use plotX/plotY):
  setPlotFrame({ xDomain, yDomain, margin }) → call ONCE before creating plots; establishes world→screen and owns resize (do not write your own plot resize handler)
  plotX(worldX) / plotY(worldY) → screen px
  compileExpr(src, vars) → f(...args); throws on a bad expression and never returns a fallback
  bindEquationInput(inputId, targets, { variables, onChange }) → wires an <input> to plot handles and shows parse errors inline
  plotFunction(id, { expr, variables, domain, samples, stroke, width, dashed }) → handle
  fillBetween(id, { lower, upper, variables, domain, samples, fill, opacity }) → handle
  plotParametric(id, { x, y, variables, tDomain, samples, stroke }) → handle
  variables: the argument names the expression may use, in order (defaults: plotFunction ['x'], fillBetween ['x'], plotParametric ['t']). When a blueprint field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotFunction('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  integrateSimpson(fn, a, b, n) → number;  findRoot(fn, a, b, tol) → number | null
  Handles re-sample on EVERY setter call, and the setters differ: plotFunction → .setExpr / .setFn / .setDomain · fillBetween → .setLower / .setUpper / .setDomain · plotParametric → .setX / .setY. All handles also have .sample() and .remove().

VISUAL FIDELITY: the default state must be a faithful inline replacement for the source image.
- Color scheme: match every color exactly — axis lines, data series, fills, backgrounds
- Layout & proportions: same relative element positions, same axis ranges, same tick marks and gridlines
- Data shape: match curve trajectories, bar heights, scatter clusters, or node/edge layout — approximate magnitudes, not invented
- Labels & annotations: every label visible in the original must appear at the same position; use blueprint.reconstructionNotes for text and color coding
- Line styles: dashed vs solid, stroke weights, arrowhead presence — copy from the image
- The step-0 (default) state should look indistinguishable from the original at a glance, with no title bar or toolbar visible

TEXT PLACEMENT & READABILITY: faithful labels must still be readable.
- Treat every label, tick label, annotation, formula, and legend item as a collision-checked box, and check each one against lines, arrows, curves, points, nodes, tick marks, gridlines, controls, and other text before finalizing. Text must not sit on top of strokes or dense marks.
- If the source label is anchored to a busy line/arrow/node, keep the semantic anchor but move the text to the nearest open whitespace and connect it with a short leader line, pointer, or subtle dot.
- Draw text and label backgrounds after geometry so labels are on top. Over busy regions add a small white/translucent background rect, or a halo: text.attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' }).
- Do not add extra visible explanatory text inside the figure; use hover tooltips, click popups, and the scaffold narration panel for explanation.

SCALE SAFETY: figures may be stitched into chapters at different sizes.
- With Canvas, Chart.js custom drawing, or any pixel-based renderer, derive point radius, stroke width, arrowheads, ticks, label size, and annotation padding from min(plotWidth, plotHeight). Avoid large fixed pixel minimums such as Math.max(20, scaledRadius); use only small clamps that prevent invisibility.
- With SVG/viewBox geometry that already scales naturally, preserve that and avoid fixed px sizes that break it.
- If space is small, simplify or hide secondary labels instead of making marks oversized.

HOVER/CLICK (on user action only): hover → showTooltip(label,event)/hideTooltip(); cursor:pointer on interactive elements. Click → showPopup('Title','2–3 sentence explanation'). Animation: fill/opacity transitions only; no scale/translate/bounce.

CONTROLS (blueprint.interactions — render in UI section; add id="{id}Input" to every input). Each control's handler must teach the concept described in its "teaches" field:
  slider → <label>{label}: <output id="{id}Val">{default}</output><input id="{id}Input" type="range" min="{min}" max="{max}" step="{step}" value="{default}" oninput="document.getElementById('{id}Val').value=this.value;update_{id}(+this.value)"></label>  +  function update_{id}(v){}
  toggle → <label><input id="{id}Input" type="checkbox" onchange="toggle_{id}(this.checked)"> {label}</label>  +  function toggle_{id}(on){}
  button → <button onclick="trigger_{id}()">{label}</button>  +  function trigger_{id}(){}
  equation_input → one <label>{field.label} <input id="{field.id}Input" value="{field.default}"></label> per entry in the interaction's "fields"
  code_editor → a <textarea id="{id}Code"> plus sample tabs, an input for the interaction's "input", a Run button, and playback controls

DEMO STEPS (blueprint.demo_steps): if present and non-empty, build a step player in #ui:
  - A <p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"> showing the current step's narration
  - <button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button>
  - Each step's .state sets matching interaction inputs to the specified values and calls their update functions
  - Step 0 is the default view (set on load); subsequent steps are one click away
  - Omit the player entirely if demo_steps is absent or empty

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Two hydrogen atoms have a potential energy minimum at a specific separation (74 pm) where nuclear–electron attraction and nucleus–nucleus repulsion balance — that separation is the covalent bond length.
KEY INSIGHT (what students should walk away understanding): A covalent bond has a definite length because energy rises in both directions from the minimum — closer costs repulsion, farther costs lost attraction — so 74 pm is the one separation where the two effects balance.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Two hydrogen atoms have a potential energy minimum at a specific separation (74 pm) where nuclear–electron attraction and nucleus–nucleus repulsion balance — that separation is the covalent bond length.",
  "figureType": "diagram",
  "elements": [
    "Pale blue plot field with thin dark border",
    "Vertical energy axis marked only with '+', '0', and '–' (no numeric scale)",
    "Horizontal dashed black zero-energy line across the full plot width",
    "Horizontal axis label 'Internuclear distance' below the plot, ending in a magenta right-pointing arrow",
    "Tall gradient arrow at far left, cream at bottom to orange at top, with rotated label 'Energy'",
    "Magenta potential-energy curve: steep repulsive wall at left descending from top, crossing zero, rounded minimum, gradual rise asymptotically approaching zero at right",
    "Two overlapping dark-green spheres at top of the repulsive branch, cyan label 'HH (too close)'",
    "Two just-touching dark-green spheres in the energy well, black label 'H—H'",
    "Two widely separated dark-green spheres at upper right, magenta dashed line joining letters 'H' and 'H' with magenta label 'H - - - H (too far)'",
    "Short vertical dashed line from the curve minimum down to the horizontal axis",
    "Green label '74 pm' beneath the dashed drop line",
    "Green arrow pointing at the minimum with green label 'Bond length'",
    "Movable marker dot on the curve driven by the distance slider",
    "Paired atom sketch that tracks the marker, with attraction/repulsion arrow cues appearing when a region is selected"
  ],
  "interactions": [
    {
      "id": "internuclearDistance",
      "type": "slider",
      "teaches": "Energy is a single-valued function of separation: pushing the atoms inside 74 pm makes energy climb steeply, pulling them apart lets it relax back toward zero, and only one separation sits at the bottom of the well.",
      "label": "Internuclear distance (pm)",
      "range": [
        30,
        300,
        1
      ],
      "default": 74
    },
    {
      "id": "curveRegion",
      "type": "click",
      "teaches": "Each part of the curve corresponds to a physical situation — repulsion-dominated overlap, balanced bonding, or two essentially independent atoms — so the curve's shape is an energy story, not just a line."
    }
  ],
  "demo_steps": [
    {
      "title": "Two free atoms",
      "narration": "Start with the hydrogen atoms far apart. The marker sits on the flat tail of the curve, essentially at zero energy — the atoms barely feel each other.",
      "state": {
        "internuclearDistance": 280
      }
    },
    {
      "title": "Attraction pulls them in",
      "narration": "As the atoms approach, each nucleus begins to attract the other's electron and the energy falls below zero. The system is becoming more stable than two separate atoms.",
      "state": {
        "internuclearDistance": 140
      }
    },
    {
      "title": "The energy minimum: bond length",
      "narration": "At 74 pm the curve bottoms out. Attraction and nucleus–nucleus repulsion exactly balance here, and this lowest-energy separation is the H—H bond length.",
      "state": {
        "internuclearDistance": 74
      }
    },
    {
      "title": "Too close: repulsion wins",
      "narration": "Squeeze the nuclei closer than 74 pm and the energy rockets up the steep wall. Positive nuclei now repel each other far more than the shared electrons can compensate.",
      "state": {
        "internuclearDistance": 45
      }
    },
    {
      "title": "Reading the whole curve",
      "narration": "Click the repulsive wall, the well, and the far tail in turn: the matching atom sketch lights up, showing why the bond has one preferred length instead of collapsing or flying apart.",
      "state": {
        "internuclearDistance": 74
      }
    }
  ],
  "keyInsight": "A covalent bond has a definite length because energy rises in both directions from the minimum — closer costs repulsion, farther costs lost attraction — so 74 pm is the one separation where the two effects balance.",
  "reconstructionNotes": "Layout: a tall cream-to-orange gradient arrow labeled 'Energy' stands outside the plot on the far left; the plot itself is a pale blue rectangle with a thin dark border. Y-axis ticks are only '+', '0', '–'; a black dashed horizontal line marks zero about 40% down from the top. The magenta curve enters at the top-left corner, plunges almost vertically, crosses zero roughly a quarter of the way across, reaches a rounded minimum near the lower-left third, then rises smoothly and flattens toward (but just below) the zero line at the right edge. Atoms are small dark-green filled circles with a lighter highlight: an overlapping pair at the very top of the steep branch with cyan text 'HH (too close)'; a just-touching pair inside the well with black text 'H—H' below it; two well-separated circles near the upper right with a magenta dashed connector between letters H and H and magenta text 'H - - - H (too far)'. A thin vertical dashed line drops from the minimum to the axis, tagged '74 pm' in green, with a green arrow and green label 'Bond length' pointing at it from the right. Below the plot, black text 'Internuclear distance' followed by a magenta arrow. Interactive marker: a filled magenta dot that slides along the curve with the distance slider, with the paired-atom sketch redrawn at matching separation directly above it. Clicking a region tints that curve segment and outlines the corresponding atom sketch, showing small red repulsion arrows (pointing apart) on the wall and blue attraction arrows (pointing together) in the well."
}

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span id="demoTitle" style="display:block;font-weight:600;font-size:12px;color:#222">Step 1 · Two free atoms</span>
<span id="demoNarration" style="display:block;font-size:11.5px;line-height:1.45;color:#333;min-height:70px">Start with the hydrogen atoms far apart. The marker sits on the flat tail of the curve, essentially at zero energy — the atoms barely feel each other.</span>
<span style="display:flex;gap:6px;align-items:center"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:11px;color:#444">Step 1 / 5</span><button onclick="nextStep()">▶</button></span>
<label>Internuclear distance: <output id="internuclearDistanceVal">74</output> pm<input id="internuclearDistanceInput" type="range" min="30" max="300" step="1" value="74" oninput="document.getElementById('internuclearDistanceVal').value=this.value;update_internuclearDistance(+this.value)"></label>
<span id="energyReadout" style="font-size:11.5px;color:#a3006b">r = 74 pm · E ≈ −436 kJ/mol</span>
<span style="font-size:11px;color:#555">Inspect a region (or click the plot):</span>
<span style="display:flex;flex-wrap:wrap;gap:4px"><button id="btn-close" onclick="trigger_curveRegion('close')">Too close</button><button id="btn-bond" onclick="trigger_curveRegion('bond')">Bond well</button><button id="btn-far" onclick="trigger_curveRegion('far')">Too far</button><button id="btn-none" onclick="trigger_curveRegion(null)">Clear</button></span>
<span style="font-size:10.5px;color:#666;line-height:1.4">Red arrows = nucleus–nucleus repulsion pushing apart. Blue arrows = attraction pulling together.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var COL = {
  magenta: '#e2007a', green: '#13793f', atom: '#12703c', atomDark: '#0a5229',
  cyan: '#2ab3e4', field: '#e3f0fa', border: '#2b2b2b', text: '#111'
};

var aM = 0.028, reB = 74, De = 436;
function Erel(r) { var t = 1 - Math.exp(-aM * (r - reB)); return t * t - 1; }

var rLo = 30, rHi = 292;
var uL = Math.log(30), uR = Math.log(300), uSpan = uR - uL;
var eTop = 1.5, eBot = -1.35, eSpan = eTop - eBot;
var XD = [uL - 0.30 * uSpan, uR + 0.08 * uSpan];
var YD = [eBot - 0.15 * eSpan, eTop + 0.04 * eSpan];

var REGION = {
  close: {
    r0: 30, r1: 58, rep: 45, tint: '#e03131',
    title: 'Too close — repulsion wins',
    body: 'Inside about 74 pm the two positively charged nuclei repel each other strongly and the electron clouds are squeezed together. The energy climbs very steeply, so pushing the atoms closer costs a great deal of energy.',
    tip: 'Repulsive wall: nuclei repel, energy rises steeply. Click for detail.'
  },
  bond: {
    r0: 58, r1: 108, rep: 74, tint: '#1d6fd0',
    title: 'The minimum — this is the bond length',
    body: 'At 74 pm the attraction of each nucleus for the other atom\'s electron exactly balances nucleus–nucleus repulsion. This lowest point lies about 436 kJ/mol below two free H atoms, and that separation is the H—H covalent bond length.',
    tip: 'Energy well: attraction and repulsion balance at 74 pm. Click for detail.'
  },
  far: {
    r0: 108, r1: 292, rep: 210, tint: '#2f8fb5',
    title: 'Too far — two independent atoms',
    body: 'Far apart, the atoms barely interact and the energy is essentially zero, the same as two isolated H atoms. Pulling a bonded pair out to here costs the full bond energy, so energy rises as separation grows past 74 pm.',
    tip: 'Flat tail: atoms barely interact, energy ≈ 0. Click for detail.'
  }
};

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
setPlotFrame({ xDomain: XD, yDomain: YD, margin: 12, draw: draw });

var px0, px1, py0, py1, pw, ph, fs, R;
var curveH = null, gRegion = null, gDyn = null, anchors = {};
var curR = 74, selRegion = null, stepIndex = 0;

function xr(r) { return plotX(Math.log(r)); }

function geom() {
  px0 = plotX(uL); px1 = plotX(uR);
  py1 = plotY(eTop); py0 = plotY(eBot);
  pw = px1 - px0; ph = py0 - py1;
  var m = Math.min(pw, ph);
  fs = Math.max(6.5, m * 0.037);
  R = Math.max(3, m * 0.026);
}

function txt(g, s, x, y, size, color, anchor, weight, halo) {
  var t = g.plain(s).font({
    family: 'Helvetica Neue, Helvetica, Arial, sans-serif',
    size: size, anchor: anchor || 'middle', weight: weight || 'normal'
  }).fill(color);
  t.attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  if (halo !== false) {
    t.attr({
      'paint-order': 'stroke', stroke: '#ffffff',
      'stroke-width': Math.max(2, size * 0.3), 'stroke-linejoin': 'round'
    });
  }
  return t;
}

function atomS(g, x, y, rad, live) {
  g.circle(rad * 2).center(x, y)
    .fill(COL.atom)
    .stroke({ color: live ? COL.magenta : COL.atomDark, width: Math.max(0.7, rad * (live ? 0.2 : 0.09)) });
  g.ellipse(rad * 0.78, rad * 0.5).center(x - rad * 0.3, y - rad * 0.38)
    .fill('#ffffff').opacity(0.30);
}

function arrow(g, x1, y1, x2, y2, color, w, op) {
  var gg = g.group();
  if (op != null) gg.opacity(op);
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var hl = Math.max(4, w * 3.4);
  gg.line(x1, y1, x2 - Math.cos(ang) * hl * 0.85, y2 - Math.sin(ang) * hl * 0.85)
    .stroke({ color: color, width: w, linecap: 'round' });
  var nx = Math.cos(ang + Math.PI / 2), ny = Math.sin(ang + Math.PI / 2);
  var pts = [
    [x2, y2],
    [x2 - Math.cos(ang) * hl + nx * hl * 0.52, y2 - Math.sin(ang) * hl + ny * hl * 0.52],
    [x2 - Math.cos(ang) * hl - nx * hl * 0.52, y2 - Math.sin(ang) * hl - ny * hl * 0.52]
  ];
  gg.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
  return gg;
}

function drawEnergyArrow() {
  var leftPx = plotX(XD[0]);
  var lm = px0 - leftPx;
  var cx = leftPx + lm * 0.44;
  var shaftW = Math.max(8, lm * 0.34);
  var headW = Math.max(14, lm * 0.62);
  var headH = Math.max(16, lm * 0.75);
  var top = py1, bot = py0;
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#ef5f22');
    add.stop(0.45, '#f7a25c');
    add.stop(1, '#fdf7d4');
  }).from(0, 0).to(0, 1);
  var pts = [
    [cx - shaftW / 2, bot], [cx + shaftW / 2, bot],
    [cx + shaftW / 2, top + headH], [cx + headW / 2, top + headH],
    [cx, top], [cx - headW / 2, top + headH], [cx - shaftW / 2, top + headH]
  ];
  draw.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill(grad).stroke({ color: '#ec6a2a', width: 1 });
  var cy = (top + bot) / 2;
  var t = txt(draw, 'Energy', cx, cy, fs * 1.05, '#111', 'middle', 'bold', false);
  t.rotate(-90, cx, cy);
}

function drawAnnotations() {
  var g = draw.group();

  // --- pair of overlapping atoms at the top of the repulsive wall ---
  var rc = 40.5, cxc = xr(rc), cyc = py1 + R * 0.15;
  atomS(g, cxc - R * 0.42, cyc, R, false);
  atomS(g, cxc + R * 0.42, cyc, R, false);
  anchors.close = { x: cxc, y: cyc, w: R * 3.2 };
  txt(g, 'HH (too close)', xr(49), plotY(1.18), fs, COL.cyan, 'start');

  // --- touching pair inside the well ---
  var cxw = xr(74), cyw = plotY(-0.40);
  atomS(g, cxw - R * 0.98, cyw, R, false);
  atomS(g, cxw + R * 0.98, cyw, R, false);
  anchors.bond = { x: cxw, y: cyw, w: R * 4.4 };
  txt(g, 'H\u2014H', cxw, plotY(-0.68), fs, COL.text, 'middle');

  // --- far-apart pair ---
  var xa = xr(115), xb = xr(200), yfar = plotY(0.58);
  atomS(g, xa, yfar, R, false);
  atomS(g, xb, yfar, R, false);
  anchors.far = { x: (xa + xb) / 2, y: yfar, w: (xb - xa) + R * 3.2 };
  var yl = plotY(0.16);
  txt(g, 'H', xa, yl, fs, COL.magenta, 'middle');
  g.line(xa + fs * 0.55, yl, xb - fs * 0.35, yl)
    .stroke({ color: COL.magenta, width: Math.max(1.1, fs * 0.11), dasharray: '5,4' });
  txt(g, 'H (too far)', xb, yl, fs * 0.95, COL.magenta, 'start');

  // --- drop line at the minimum + 74 pm ---
  g.line(cxw, plotY(-1.0), cxw, plotY(-1.18))
    .stroke({ color: '#444', width: 1, dasharray: '4,3' });
  txt(g, '74 pm', cxw, plotY(-1.29), fs * 0.95, COL.green, 'middle');

  // --- bond length label + green arrow ---
  var tx = xr(132), ty = plotY(-1.10);
  txt(g, 'Bond length', tx, ty, fs, COL.green, 'start');
  arrow(g, tx - fs * 0.55, ty, cxw + R * 0.55, plotY(-1.06), COL.green, Math.max(1.2, fs * 0.12));

  // --- axis tick labels ---
  var lx = px0 - fs * 0.85;
  txt(g, '+', lx, plotY(0.72), fs * 1.3, COL.text, 'end', 'normal', false);
  txt(g, '0', lx, plotY(0), fs * 1.15, COL.text, 'end', 'normal', false);
  txt(g, '\u2212', lx, plotY(-0.72), fs * 1.3, COL.text, 'end', 'normal', false);

  // --- x axis caption ---
  var bottomGap = plotY(YD[0]) - py0;
  var ylab = py0 + bottomGap * 0.52;
  var xc = px0 + pw * 0.58;
  txt(g, 'Internuclear distance', xc, ylab, fs * 1.05, COL.text, 'end', 'normal', false);
  arrow(g, xc + fs * 0.6, ylab, xc + fs * 3.6, ylab, COL.magenta, Math.max(1.6, fs * 0.16));
}

function drawRegionTint() {
  if (!gRegion) return;
  gRegion.clear();
  if (!selRegion) return;
  var reg = REGION[selRegion];
  var x0 = xr(reg.r0), x1 = xr(reg.r1);
  gRegion.rect(x1 - x0, ph).move(x0, py1).fill({ color: reg.tint, opacity: 0.09 });
  var pts = [];
  for (var i = 0; i <= 160; i++) {
    var r = reg.r0 + (reg.r1 - reg.r0) * i / 160;
    var e = Erel(r);
    if (e > eTop) continue;
    pts.push(xr(r) + ',' + plotY(e));
  }
  if (pts.length > 1) {
    gRegion.polyline(pts.join(' ')).fill('none')
      .stroke({ color: reg.tint, width: R * 0.95, opacity: 0.42, linecap: 'round', linejoin: 'round' });
  }
}

function cueArrows(g, sx, sy, sep, rad) {
  if (!selRegion) return;
  var reg = selRegion;
  var col = (reg === 'close') ? '#e03131' : '#1d6fd0';
  var op = (reg === 'far') ? 0.4 : 1;
  var L = rad * 2.0;
  var w = Math.max(1.2, rad * 0.24);
  var lx = sx - sep / 2, rx = sx + sep / 2;
  if (reg === 'close') {
    arrow(g, lx - rad * 0.9, sy, lx - rad * 0.9 - L, sy, col, w, op);
    arrow(g, rx + rad * 0.9, sy, rx + rad * 0.9 + L, sy, col, w, op);
  } else {
    arrow(g, lx - rad * 0.9 - L, sy, lx - rad * 0.9, sy, col, w, op);
    arrow(g, rx + rad * 0.9 + L, sy, rx + rad * 0.9, sy, col, w, op);
  }
}

function drawDynamic() {
  if (!gDyn) return;
  gDyn.clear();
  var r = Math.max(rLo, Math.min(rHi, curR));
  var e = Erel(r);
  var eC = Math.min(e, eTop - 0.05);
  var mx = xr(r), my = plotY(eC);

  var rad = R * 0.78;
  var sep = Math.min(2 * rad * (r / reB), 6.2 * rad);
  var below = (e > -0.35);
  var sy = below ? (my + rad * 3.6) : (my - rad * 3.6);
  sy = Math.max(py1 + rad * 1.8, Math.min(py0 - rad * 1.8, sy));
  var L = rad * 2.0;
  var pad = rad + (selRegion ? (L + rad * 1.1) : rad * 0.8);
  var sx = mx;
  var loX = px0 + sep / 2 + pad, hiX = px1 - sep / 2 - pad;
  if (loX < hiX) sx = Math.max(loX, Math.min(hiX, mx));

  gDyn.line(mx, my, sx, sy).stroke({ color: COL.magenta, width: 1, opacity: 0.4, dasharray: '3,3' });
  atomS(gDyn, sx - sep / 2, sy, rad, true);
  atomS(gDyn, sx + sep / 2, sy, rad, true);
  cueArrows(gDyn, sx, sy, sep, rad);

  var mk = gDyn.circle(R * 0.95).center(mx, my).fill(COL.magenta)
    .stroke({ color: '#ffffff', width: Math.max(1.2, R * 0.18) });
  mk.css('cursor', 'pointer');
  mk.on('mousemove', function (ev) {
    showTooltip('r = ' + Math.round(curR) + ' pm · E ≈ ' + Math.round(De * Erel(curR)) + ' kJ/mol', ev);
  }).on('mouseleave', hideTooltip);

  if (selRegion && anchors[selRegion]) {
    var A = anchors[selRegion];
    gDyn.rect(A.w, R * 2.9).center(A.x, A.y).radius(R * 0.7)
      .fill('none').stroke({ color: REGION[selRegion].tint, width: Math.max(1.2, R * 0.16), dasharray: '5,4' });
  }
}

function drawHits() {
  var g = draw.group();
  Object.keys(REGION).forEach(function (k) {
    var reg = REGION[k];
    var x0 = xr(reg.r0), x1 = xr(Math.min(reg.r1, 300));
    var rect = g.rect(x1 - x0, ph).move(x0, py1).fill({ color: '#ffffff', opacity: 0.001 });
    rect.css('cursor', 'pointer');
    rect.on('mousemove', function (ev) { showTooltip(reg.tip, ev); });
    rect.on('mouseleave', hideTooltip);
    rect.on('click', function () { trigger_curveRegion(k); });
  });
}

function rebuild() {
  if (curveH) { try { curveH.remove(); } catch (e) { } curveH = null; }
  draw.clear();
  geom();
  if (pw <= 10 || ph <= 10) return;

  drawEnergyArrow();

  draw.rect(pw, ph).move(px0, py1).fill(COL.field)
    .stroke({ color: COL.border, width: 1.2 });

  draw.line(px0, plotY(0), px1, plotY(0))
    .stroke({ color: '#111', width: Math.max(1.2, fs * 0.1), dasharray: '9,6' });

  gRegion = draw.group();

  curveH = plotFunction('pe', {
    fn: function (u) {
      var e = Erel(Math.exp(u));
      return (e > eTop) ? NaN : e;
    },
    domain: [Math.log(rLo), Math.log(rHi)],
    samples: 500,
    stroke: COL.magenta,
    width: Math.max(2, Math.min(pw, ph) * 0.0085)
  });

  drawAnnotations();
  gDyn = draw.group();
  drawHits();

  drawRegionTint();
  drawDynamic();
}

function describe(r) {
  if (r < 62) return 'repulsion dominates';
  if (r < 88) return 'at the minimum — bonded';
  if (r < 160) return 'attraction still pulling them in';
  return 'essentially two free atoms';
}

function updateReadout() {
  var el = document.getElementById('energyReadout');
  if (!el) return;
  var e = Math.round(De * Erel(curR));
  var s = (e > 0 ? '+' : (e < 0 ? '\u2212' : '')) + Math.abs(e);
  el.textContent = 'r = ' + Math.round(curR) + ' pm · E \u2248 ' + s + ' kJ/mol — ' + describe(curR);
}

function update_internuclearDistance(v) {
  curR = +v;
  updateReadout();
  drawDynamic();
}

function setDistance(v) {
  curR = +v;
  var inp = document.getElementById('internuclearDistanceInput');
  if (inp) inp.value = v;
  var out = document.getElementById('internuclearDistanceVal');
  if (out) out.value = v;
  updateReadout();
  drawDynamic();
}

function trigger_curveRegion(id, quiet) {
  selRegion = id || null;
  ['close', 'bond', 'far'].forEach(function (k) {
    var b = document.getElementById('btn-' + k);
    if (b) { if (k === selRegion) b.classList.add('active'); else b.classList.remove('active'); }
  });
  if (selRegion && !quiet) {
    setDistance(REGION[selRegion].rep);
    showPopup(REGION[selRegion].title, REGION[selRegion].body);
  }
  drawRegionTint();
  drawDynamic();
}

