Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span id="demoTitle" style="display:block;font-weight:600;font-size:12px;color:#222">Step 1 · Two free atoms</span>
<span id="demoNarration" style="display:block;font-size:11.5px;line-height:1.45;color:#333;min-height:72px">Start with the hydrogen atoms far apart. The marker sits on the flat tail of the curve, essentially at zero energy — the atoms barely feel each other.</span>
<span style="display:flex;gap:6px;align-items:center"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:11px;color:#444">Step 1 / 5</span><button onclick="nextStep()">▶</button></span>
<label>Internuclear distance: <output id="internuclearDistanceVal">74</output> pm<input id="internuclearDistanceInput" type="range" min="30" max="300" step="1" value="74" oninput="document.getElementById('internuclearDistanceVal').value=this.value;update_internuclearDistance(+this.value)"></label>
<span id="energyReadout" style="font-size:11.5px;color:#a3006b">r = 74 pm · E ≈ −436 kJ/mol</span>
<span style="font-size:11px;color:#555">Inspect a region (or click the plot):</span>
<span style="display:flex;flex-wrap:wrap;gap:4px"><button id="btn-close" onclick="trigger_curveRegion('close')">Too close</button><button id="btn-bond" onclick="trigger_curveRegion('bond')">Bond well</button><button id="btn-far" onclick="trigger_curveRegion('far')">Too far</button><button id="btn-none" onclick="trigger_curveRegion(null)">Clear</button></span>
<span style="font-size:10.5px;color:#666;line-height:1.4">Move the slider, step forward, or pick a region: a magenta marker appears on the curve and a live atom pair is sketched above it. Red arrows = nucleus–nucleus repulsion pushing apart; blue arrows = attraction pulling together.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var COL = {
  magenta: '#e2007a', green: '#13793f', atom: '#12703c', atomDark: '#0a5229',
  cyan: '#2ab3e4', field: '#e3f0fa', border: '#2b2b2b', text: '#111'
};

var aM = 0.028, reB = 74, De = 436;
function Erel(r) { var t = 1 - Math.exp(-aM * (r - reB)); return t * t - 1; }

var rLo = 30, rHi = 300;
var uL = Math.log(30), uR = Math.log(700), uSpan = uR - uL;
var eTop = 1.5, eBot = -1.45, eSpan = eTop - eBot;
var XD = [uL - 0.24 * uSpan, uR + 0.02 * uSpan];
var YD = [eBot - 0.10 * eSpan, eTop + 0.14 * eSpan];

var REGION = {
  close: {
    r0: 30, r1: 58, rep: 45, tint: '#e03131',
    title: 'Too close — repulsion wins',
    body: 'Inside about 74 pm the two positively charged nuclei repel each other strongly and the electron clouds are squeezed together. The energy climbs very steeply, so pushing the atoms closer costs a great deal of energy.',
    tip: 'Repulsive wall: nuclei repel, energy rises steeply. Click for detail.'
  },
  bond: {
    r0: 58, r1: 108, rep: 74, tint: '#1d6fd0',
    title: 'The minimum — this is the bond length',
    body: 'At 74 pm the attraction of each nucleus for the other atom\'s electron exactly balances nucleus–nucleus repulsion. This lowest point lies about 436 kJ/mol below two free H atoms, and that separation is the H—H covalent bond length.',
    tip: 'Energy well: attraction and repulsion balance at 74 pm. Click for detail.'
  },
  far: {
    r0: 108, r1: 300, rep: 210, tint: '#2f8fb5',
    title: 'Too far — two independent atoms',
    body: 'Far apart, the atoms barely interact and the energy is essentially zero, the same as two isolated H atoms. Pulling a bonded pair out to here costs the full bond energy, so energy rises as separation grows past 74 pm.',
    tip: 'Flat tail: atoms barely interact, energy ≈ 0. Click for detail.'
  }
};

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
setPlotFrame({ xDomain: XD, yDomain: YD, margin: 12, draw: draw });

var px0, px1, py0, py1, pw, ph, fs, R, yBand, topPairX;
var curveH = null, gRegion = null, gDyn = null, anchors = {}, topPairG = null;
var curR = 74, selRegion = null, stepIndex = 0, liveOn = false;

function xr(r) { return plotX(Math.log(r)); }

function geom() {
  px0 = plotX(uL); px1 = plotX(uR);
  py1 = plotY(eTop); py0 = plotY(eBot);
  pw = px1 - px0; ph = py0 - py1;
  var m = Math.min(pw, ph);
  fs = Math.max(6.5, m * 0.038);
  R = Math.max(3, m * 0.026);
  yBand = py1 - R * 1.9;
  yBand = Math.max(R * 1.3 + 2, yBand);
  topPairX = xr(42);
}

function txt(g, s, x, y, size, color, anchor, weight, halo) {
  var t = g.plain(s).font({
    family: 'Helvetica Neue, Helvetica, Arial, sans-serif',
    size: size, anchor: anchor || 'middle', weight: weight || 'normal'
  }).fill(color);
  t.attr({ x: x, y: y, 'dominant-baseline': 'middle', 'pointer-events': 'none' });
  if (halo !== false) {
    t.attr({
      'paint-order': 'stroke', stroke: '#ffffff',
      'stroke-width': Math.max(2, size * 0.3), 'stroke-linejoin': 'round'
    });
  }
  return t;
}

function atomS(g, x, y, rad, live) {
  g.circle(rad * 2).center(x, y)
    .fill(COL.atom)
    .stroke({ color: live ? COL.magenta : COL.atomDark, width: Math.max(0.7, rad * (live ? 0.22 : 0.09)) });
  g.ellipse(rad * 0.78, rad * 0.5).center(x - rad * 0.3, y - rad * 0.38)
    .fill('#ffffff').opacity(0.30);
}

function arrow(g, x1, y1, x2, y2, color, w, op) {
  var gg = g.group();
  if (op != null) gg.opacity(op);
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var hl = Math.max(4, w * 3.4);
  gg.line(x1, y1, x2 - Math.cos(ang) * hl * 0.85, y2 - Math.sin(ang) * hl * 0.85)
    .stroke({ color: color, width: w, linecap: 'round' });
  var nx = Math.cos(ang + Math.PI / 2), ny = Math.sin(ang + Math.PI / 2);
  var pts = [
    [x2, y2],
    [x2 - Math.cos(ang) * hl + nx * hl * 0.52, y2 - Math.sin(ang) * hl + ny * hl * 0.52],
    [x2 - Math.cos(ang) * hl - nx * hl * 0.52, y2 - Math.sin(ang) * hl - ny * hl * 0.52]
  ];
  gg.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
  gg.attr('pointer-events', 'none');
  return gg;
}

function drawEnergyArrow() {
  var leftPx = plotX(XD[0]);
  var lm = px0 - leftPx;
  var cx = leftPx + lm * 0.36;
  var shaftW = Math.max(5, lm * 0.20);
  var headW = Math.max(11, lm * 0.46);
  var headH = Math.max(13, lm * 0.50);
  var top = py1 - lm * 0.16;
  var bot = py0 + lm * 0.16;
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#ef5f22');
    add.stop(0.45, '#f7a25c');
    add.stop(1, '#fdf7d4');
  }).from(0, 0).to(0, 1);
  var pts = [
    [cx - shaftW / 2, bot], [cx + shaftW / 2, bot],
    [cx + shaftW / 2, top + headH], [cx + headW / 2, top + headH],
    [cx, top], [cx - headW / 2, top + headH], [cx - shaftW / 2, top + headH]
  ];
  draw.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill(grad).stroke({ color: '#ec6a2a', width: 1 }).attr('pointer-events', 'none');
  var cy = (top + bot) / 2;
  var t = txt(draw, 'Energy', cx, cy, fs * 1.0, '#111', 'middle', 'bold', false);
  t.rotate(-90, cx, cy);
}

function drawAnnotations() {
  var g = draw.group();

  // --- static "too close" pair straddling the top frame border ---
  topPairG = g.group();
  atomS(topPairG, topPairX - R * 0.42, py1, R, false);
  atomS(topPairG, topPairX + R * 0.42, py1, R, false);
  topPairG.attr('pointer-events', 'none');
  anchors.close = { x: topPairX, y: py1, w: R * 3.1, h: R * 2.8 };

  // cyan label beside the steep wall
  txt(g, 'HH (too close)', xr(47), plotY(1.20), fs, COL.cyan, 'start');

  // --- touching pair inside the well ---
  var cxw = xr(74), cyw = plotY(-0.48);
  atomS(g, cxw - R * 0.98, cyw, R, false);
  atomS(g, cxw + R * 0.98, cyw, R, false);
  anchors.bond = { x: cxw, y: cyw, w: R * 4.6, h: R * 2.8 };
  txt(g, 'H\u2014H', cxw, plotY(-0.78), fs, COL.text, 'middle');

  // --- far-apart pair, pushed right over the flat tail ---
  var xa = xr(170), xb = xr(300), yfar = plotY(0.37);
  atomS(g, xa, yfar, R, false);
  atomS(g, xb, yfar, R, false);
  anchors.far = { x: (xa + xb) / 2, y: yfar, w: (xb - xa) + R * 3.2, h: R * 2.8 };
  var yl = plotY(0.10);
  txt(g, 'H', xa, yl, fs, COL.magenta, 'middle');
  g.line(xa + fs * 0.55, yl, xb - fs * 0.45, yl)
    .stroke({ color: COL.magenta, width: Math.max(1.1, fs * 0.11), dasharray: '5,4' })
    .attr('pointer-events', 'none');
  txt(g, 'H (too far)', xb + fs * 0.1, yl, fs * 0.95, COL.magenta, 'start');

  // --- long dashed drop line from the minimum down to the 74 pm label ---
  g.line(cxw, plotY(-1.015), cxw, plotY(-1.30))
    .stroke({ color: '#444', width: Math.max(1, fs * 0.09), dasharray: '4,3' })
    .attr('pointer-events', 'none');
  txt(g, '74 pm', cxw, plotY(-1.38), fs * 0.95, COL.green, 'middle');

  // --- bond length label + green arrow to the minimum ---
  var tx = xr(118), ty = plotY(-1.10);
  txt(g, 'Bond length', tx, ty, fs, COL.green, 'start');
  arrow(g, tx - fs * 0.45, ty, cxw + R * 0.7, plotY(-1.045), COL.green, Math.max(1.2, fs * 0.12));

  // --- axis tick labels ---
  var lx = px0 - fs * 0.8;
  txt(g, '+', lx, plotY(0.72), fs * 1.3, COL.text, 'end', 'normal', false);
  txt(g, '0', lx, plotY(0), fs * 1.15, COL.text, 'end', 'normal', false);
  txt(g, '\u2212', lx, plotY(-0.72), fs * 1.3, COL.text, 'end', 'normal', false);

  // --- x axis caption ---
  var bottomGap = plotY(YD[0]) - py0;
  var ylab = py0 + bottomGap * 0.55;
  var xc = px0 + pw * 0.56;
  txt(g, 'Internuclear distance', xc, ylab, fs * 1.05, COL.text, 'end', 'normal', false);
  arrow(g, xc + fs * 0.6, ylab, xc + fs * 4.2, ylab, COL.magenta, Math.max(1.6, fs * 0.16));
}

function drawRegionTint() {
  if (!gRegion) return;
  gRegion.clear();
  if (!selRegion) return;
  var reg = REGION[selRegion];
  var x0 = xr(reg.r0), x1 = (selRegion === 'far') ? px1 : xr(reg.r1);
  gRegion.rect(x1 - x0, ph).move(x0, py1).fill({ color: reg.tint, opacity: 0.09 });
  var pts = [];
  for (var i = 0; i <= 200; i++) {
    var r = reg.r0 + (Math.min(reg.r1, rHi) - reg.r0) * i / 200;
    var e = Erel(r);
    if (e > eTop) continue;
    pts.push(xr(r) + ',' + plotY(e));
  }
  if (pts.length > 1) {
    gRegion.polyline(pts.join(' ')).fill('none')
      .stroke({ color: reg.tint, width: R * 0.95, opacity: 0.42, linecap: 'round', linejoin: 'round' });
  }
}

function cueArrows(g, sx, sy, sep, rad) {
  if (!selRegion) return;
  var col = (selRegion === 'close') ? '#e03131' : '#1d6fd0';
  var op = (selRegion === 'far') ? 0.42 : 1;
  var L = rad * 2.0;
  var w = Math.max(1.2, rad * 0.24);
  var lx = sx - sep / 2, rx = sx + sep / 2;
  if (selRegion === 'close') {
    arrow(g, lx - rad * 0.9, sy, lx - rad * 0.9 - L, sy, col, w, op);
    arrow(g, rx + rad * 0.9, sy, rx + rad * 0.9 + L, sy, col, w, op);
  } else {
    arrow(g, lx - rad * 0.9 - L, sy, lx - rad * 0.9, sy, col, w, op);
    arrow(g, rx + rad * 0.9 + L, sy, rx + rad * 0.9, sy, col, w, op);
  }
}

function drawDynamic() {
  if (!gDyn) return;
  gDyn.clear();
  if (topPairG) topPairG.opacity(1);
  if (!liveOn) return;   // step-0 / untouched state is a faithful static copy

  var r = Math.max(rLo, Math.min(rHi, curR));
  var e = Erel(r);
  var eC = Math.min(e, eTop - 0.04);
  var mx = xr(r), my = plotY(eC);

  var rad = R * 0.78;
  var sep = Math.min(2 * rad * (r / reB), 6.2 * rad);
  var L = rad * 2.0;
  var halfW = sep / 2 + rad + (selRegion ? (L + rad * 0.9) : rad * 0.4);

  var sx = mx;
  var loX = px0 + halfW, hiX = px1 - halfW;
  if (loX < hiX) sx = Math.max(loX, Math.min(hiX, mx));

  // never sit on top of the static "too close" pair on the top border
  var keepOut = halfW + R * 2.3;
  if (Math.abs(sx - topPairX) < keepOut) {
    var rightSlot = topPairX + keepOut, leftSlot = topPairX - keepOut;
    if (rightSlot <= hiX) sx = rightSlot;
    else if (leftSlot >= loX) sx = leftSlot;
    else topPairG.opacity(0.18);
  }

  // faint leader tying the live sketch to the marker on the curve
  gDyn.line(mx, my, sx, yBand + rad * 1.35)
    .stroke({ color: COL.magenta, width: 1, opacity: 0.26, dasharray: '3,4' })
    .attr('pointer-events', 'none');

  atomS(gDyn, sx - sep / 2, yBand, rad, true);
  atomS(gDyn, sx + sep / 2, yBand, rad, true);
  cueArrows(gDyn, sx, yBand, sep, rad);

  var mk = gDyn.circle(R * 0.95).center(mx, my).fill(COL.magenta)
    .stroke({ color: '#ffffff', width: Math.max(1.2, R * 0.18) });
  mk.css('cursor', 'pointer');
  mk.on('mousemove', function (ev) {
    showTooltip('r = ' + Math.round(curR) + ' pm · E \u2248 ' + Math.round(De * Erel(curR)) + ' kJ/mol', ev);
  }).on('mouseleave', hideTooltip);

  if (selRegion && anchors[selRegion]) {
    var A = anchors[selRegion];
    gDyn.rect(A.w, A.h).center(A.x, A.y).radius(R * 0.7)
      .fill('none').stroke({ color: REGION[selRegion].tint, width: Math.max(1.2, R * 0.16), dasharray: '5,4' })
      .attr('pointer-events', 'none');
  }
}

function drawHits() {
  var g = draw.group();
  Object.keys(REGION).forEach(function (k) {
    var reg = REGION[k];
    var x0 = xr(reg.r0), x1 = (k === 'far') ? px1 : xr(reg.r1);
    var rect = g.rect(x1 - x0, ph).move(x0, py1).fill({ color: '#ffffff', opacity: 0.001 });
    rect.css('cursor', 'pointer');
    rect.on('mousemove', function (ev) { showTooltip(reg.tip, ev); });
    rect.on('mouseleave', hideTooltip);
    rect.on('click', function () { trigger_curveRegion(k); });
  });
}

function rebuild() {
  if (curveH) { try { curveH.remove(); } catch (e) { } curveH = null; }
  draw.clear();
  geom();
  if (pw <= 10 || ph <= 10) return;

  drawEnergyArrow();

  draw.rect(pw, ph).move(px0, py1).fill(COL.field)
    .stroke({ color: COL.border, width: 1.2 });

  draw.line(px0, plotY(0), px1, plotY(0))
    .stroke({ color: '#111', width: Math.max(1.2, fs * 0.1), dasharray: '9,6' })
    .attr('pointer-events', 'none');

  gRegion = draw.group();

  curveH = plotFunction('pe', {
    fn: function (u) {
      var e = Erel(Math.exp(u));
      return (e > eTop) ? NaN : e;
    },
    domain: [Math.log(rLo), Math.log(rHi)],
    samples: 560,
    stroke: COL.magenta,
    width: Math.max(2, Math.min(pw, ph) * 0.0088)
  });
  curveH.node.attr('pointer-events', 'none');

  drawHits();
  drawAnnotations();
  gDyn = draw.group();

  drawRegionTint();
  drawDynamic();
}

function describe(r) {
  if (r < 62) return 'repulsion dominates';
  if (r < 88) return 'at the minimum — bonded';
  if (r < 160) return 'attraction still pulling them in';
  return 'essentially two free atoms';
}

function updateReadout() {
  var el = document.getElementById('energyReadout');
  if (!el) return;
  var e = Math.round(De * Erel(curR));
  var s = (e > 0 ? '+' : (e < 0 ? '\u2212' : '')) + Math.abs(e);
  el.textContent = 'r = ' + Math.round(curR) + ' pm · E \u2248 ' + s + ' kJ/mol — ' + describe(curR);
}

function update_internuclearDistance(v) {
  curR = +v;
  liveOn = true;
  updateReadout();
  drawDynamic();
}

function setDistance(v) {
  curR = +v;
  var inp = document.getElementById('internuclearDistanceInput');
  if (inp) inp.value = v;
  var out = document.getElementById('internuclearDistanceVal');
  if (out) out.value = v;
  updateReadout();
  drawDynamic();
}

function trigger_curveRegion(id, quiet) {
  selRegion = id || null;
  ['close', 'bond', 'far'].forEach(function (k) {
    var b = document.getElementById('btn-' + k);
    if (b) { if (k === selRegion) b.classList.add('active'); else b.classList.remove('active'); }
  });
  if (!quiet) liveOn = true;
  if (selRegion && !quiet) {
    setDistance(REGION[selRegion].rep);
    showPopup(REGION[selRegion].title, REGION[selRegion].body);
  }
  drawRegionTint();
  drawDynamic();
}

var steps = [
  {
    title: 'Two free atoms',
    narration: 'The textbook figure: two hydrogen atoms far apart sit on the flat tail of the curve, essentially at zero energy — they barely feel each other. Press \u25b6 (or move the slider) to bring them together.',
    state: { internuclearDistance: 280, region: null }
  },
  {
    title: 'Attraction pulls them in',
    narration: 'As the atoms approach, each nucleus begins to attract the other\'s electron and the energy falls below zero. The system is becoming more stable than two separate atoms.',
    state: { internuclearDistance: 140, region: null }
  },
  {
    title: 'The energy minimum: bond length',
    narration: 'At 74 pm the curve bottoms out. Attraction and nucleus–nucleus repulsion exactly balance here, and this lowest-energy separation is the H—H bond length.',
    state: { internuclearDistance: 74, region: 'bond' }
  },
  {
    title: 'Too close: repulsion wins',
    narration: 'Squeeze the nuclei closer than 74 pm and the energy rockets up the steep wall. Positive nuclei now repel each other far more than the shared electrons can compensate.',
    state: { internuclearDistance: 45, region: 'close' }
  },
  {
    title: 'Reading the whole curve',
    narration: 'Energy rises in both directions from the minimum — closer costs repulsion, farther costs lost attraction — so the bond has one preferred length. Click the wall, the well and the tail to compare them.',
    state: { internuclearDistance: 74, region: null }
  }
];

function setStep(i, initial) {
  stepIndex = ((i % steps.length) + steps.length) % steps.length;
  var s = steps[stepIndex];
  var t = document.getElementById('demoTitle');
  if (t) t.textContent = 'Step ' + (stepIndex + 1) + ' · ' + s.title;
  var n = document.getElementById('demoNarration');
  if (n) n.textContent = s.narration;
  var l = document.getElementById('stepLabel');
  if (l) l.textContent = 'Step ' + (stepIndex + 1) + ' / ' + steps.length;
  if (!initial) liveOn = true;
  setDistance(s.state.internuclearDistance);
  trigger_curveRegion(s.state.region, true);
}

function nextStep() { liveOn = true; setStep(stepIndex + 1); }
function prevStep() { liveOn = true; setStep(stepIndex - 1); }

document.addEventListener('fig-resize', function () {
  rebuild();
});

rebuild();
